// Módulos administrativos complementares — usam as tabelas e RPCs do Script 4.
import { $, $$, esc, brl, fmtDate, fmtTime, toast, confirmBox, onlyDigits } from './common.js';
import { api } from './api.js';

const money = (v) => Number(v || 0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const q = (v) => encodeURIComponent(v ?? '');
const wrap = (title, actions, content) => `<div class="row" style="justify-content:space-between;align-items:center;flex-wrap:wrap"><h2>${title}</h2><div class="row">${actions||''}</div></div>${content}`;
function dlg(html){const d=document.createElement('dialog');d.className='dlg big';d.innerHTML=html;document.body.append(d);d.addEventListener('close',()=>d.remove());d.showModal();$$('[data-close]',d).forEach(b=>b.onclick=e=>{e.preventDefault();d.close()});return d;}
const guard=async fn=>{try{return await fn()}catch(e){toast(e.message||'Erro ao executar.','error')}};
const field=(id,label,type='text',value='',extra='')=>`<label for="${id}">${label}</label><input id="${id}" type="${type}" value="${esc(value??'')}" ${extra}>`;
const saveForm=(d,id,fn)=>{const f=$('#'+id,d);f.onsubmit=async e=>{e.preventDefault();const b=$('button[type=submit]',f);if(b)b.disabled=true;try{await fn();d.close()}catch(x){$('#err',d).textContent=x.message;b&&(b.disabled=false)}}};

export async function viewCaixa(root){
 let data=null, sessions=[]; let error='';
 try{[data,sessions]=await Promise.all([api.rpc('cash_summary'),api.select('cash_sessions','select=*&order=opened_at.desc&limit=20')]);}catch(e){error=e.message||'Não foi possível carregar o caixa.';}
 const isOpen=data?.status==='open';
 const movements=data?.movements||[];
 root.innerHTML=wrap('Caixa',isOpen?'<button class="btn small" id="refresh">Atualizar</button><button class="btn small" id="mov">+ Movimentação</button><button class="btn small" id="closecash">Fechar caixa</button>':'<button class="btn" id="opencash">Abrir caixa</button>',
 (error?`<div class="notice error">${esc(error)}</div>`:data?`<div class="stats"><div class="stat">Saldo inicial<b>${money(data.opening_amount)}</b></div><div class="stat">Dinheiro esperado<b>${money(data.expected_cash)}</b></div><div class="stat">Entradas em dinheiro<b>${money(data.manual_in)}</b></div><div class="stat">Saídas em dinheiro<b>${money(data.manual_out)}</b></div></div><div class="card"><h3>Recebimentos por forma</h3>${Object.entries(data.payments_by_method||{}).map(([k,v])=>`<p>${esc(({cash:'Dinheiro',pix:'Pix',debit:'Débito',credit:'Crédito',other:'Outro'})[k]||k)} <b>${money(v)}</b></p>`).join('')||'Nenhum recebimento.'}</div><div class="card"><h3>Movimentações manuais</h3>${movements.length?`<div class="tbl-scroll"><table class="t"><thead><tr><th>Data</th><th>Tipo</th><th>Motivo</th><th>Forma</th><th>Valor</th></tr></thead><tbody>${movements.slice().reverse().map(m=>`<tr><td>${fmtDate(m.at)} ${fmtTime(m.at)}</td><td>${m.kind==='in'?'Entrada':'Saída'}</td><td>${esc(m.reason)}</td><td>${esc(m.method)}</td><td>${money(m.amount)}</td></tr>`).join('')}</tbody></table></div>`:'Nenhuma movimentação manual neste caixa.'}</div>`:'<div class="notice">Não há caixa aberto. Abra um caixa para registrar entradas e saídas.</div>')+`<h3>Histórico de caixas</h3><div class="card">${sessions.map(x=>`<div class="svc"><div><b>${fmtDate(x.opened_at)} ${fmtTime(x.opened_at)}</b><br><span class="muted">${x.status==='open'?'Aberto':'Fechado'} · Inicial ${money(x.opening_amount)} · Esperado ${money(x.expected_cash)} · Contado ${money(x.counted_cash)}</span>${x.difference!=null?`<br>Diferença: <b>${money(x.difference)}</b>`:''}${x.note?`<br><span class="muted">${esc(x.note)}</span>`:''}</div></div>`).join('')||'Sem histórico.'}</div>`);
 $('#refresh')?.addEventListener('click',()=>viewCaixa(root));
 $('#opencash')?.addEventListener('click',()=>{const d=dlg(`<form id="cashf"><h2>Abrir caixa</h2>${field('amount','Valor inicial (R$)','number','0','min="0" step="0.01" required')}<p class="err" id="err"></p><button class="btn" type="submit">Abrir caixa</button></form>`);saveForm(d,'cashf',async()=>{await api.rpc('cash_open',{p_amount:Number($('#amount',d).value)});toast('Caixa aberto.','success');await viewCaixa(root)})});
 $('#mov')?.addEventListener('click',()=>{const d=dlg(`<form id="movf"><h2>Registrar movimentação</h2><label>Tipo</label><select id="kind"><option value="in">Entrada</option><option value="out">Saída</option></select>${field('amount','Valor (R$)','number','','min="0.01" step="0.01" required')} ${field('reason','Motivo / descrição','text','','required maxlength="160"')}<label>Forma de pagamento</label><select id="method"><option value="cash">Dinheiro</option><option value="pix">Pix</option><option value="debit">Débito</option><option value="credit">Crédito</option><option value="other">Outro</option></select><p class="err" id="err"></p><button class="btn" type="submit">Salvar movimentação</button></form>`);saveForm(d,'movf',async()=>{await api.rpc('cash_add_movement',{p_kind:$('#kind',d).value,p_amount:Number($('#amount',d).value),p_reason:$('#reason',d).value.trim(),p_method:$('#method',d).value});toast('Movimentação registrada.','success');await viewCaixa(root)})});
 $('#closecash')?.addEventListener('click',()=>{const d=dlg(`<form id="closef"><h2>Fechar caixa</h2>${field('counted','Dinheiro contado (R$)','number','','min="0" step="0.01" required')}${field('note','Observação','text','','maxlength="250"')}<p class="err" id="err"></p><button class="btn" type="submit">Conferir e fechar</button></form>`);saveForm(d,'closef',async()=>{const r=await api.rpc('cash_close',{p_counted:Number($('#counted',d).value),p_note:$('#note',d).value.trim()||null});toast('Caixa fechado. Diferença: '+money(r.difference),'success');await viewCaixa(root)})});
}

export async function viewProdutos(root){
 const [rows,cats]=await Promise.all([api.select('products','select=*,product_categories(name)&order=name'),api.select('product_categories','select=*&order=name')]);
 root.innerHTML=wrap('Produtos e estoque','<button class="btn" id="add">+ Produto</button>',`<div class="card tbl-scroll"><table class="t"><thead><tr><th>Produto</th><th>Preço</th><th>Custo</th><th>Estoque</th><th></th></tr></thead><tbody>${rows.map(p=>`<tr><td>${esc(p.name)}${p.quantity<=p.low_stock_limit?' <span class="badge warn">Estoque baixo</span>':''}</td><td>${money(p.price)}</td><td>${money(p.cost)}</td><td>${p.quantity}</td><td><button class="btn small ghost" data-edit="${p.id}">Editar</button> <button class="btn small ghost" data-stock="${p.id}">Movimentar</button></td></tr>`).join('')}</tbody></table></div>`);
 const form=p=>{const d=dlg(`<form id="pf"><h2>${p?'Editar':'Novo'} produto</h2>${field('name','Nome','text',p?.name)}${field('description','Descrição','text',p?.description)}${field('price','Preço (R$)','number',p?.price??'','min="0" step="0.01"')}${field('cost','Custo (R$)','number',p?.cost??'0','min="0" step="0.01"')}${field('quantity','Quantidade em estoque','number',p?.quantity??'0','min="0" step="1"')}${field('limit','Avisar quando chegar a','number',p?.low_stock_limit??'2','min="0" step="1"')}<label>Categoria</label><select id="cat"><option value="">Sem categoria</option>${cats.map(c=>`<option value="${c.id}" ${p?.category_id===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select><label class="check"><input id="active" type="checkbox" ${p?.is_active===false?'':'checked'}> Ativo</label><p class="err" id="err"></p><button class="btn" type="submit">Salvar</button></form>`);saveForm(d,'pf',async()=>{const v={name:$('#name',d).value.trim(),description:$('#description',d).value.trim(),price:Number($('#price',d).value),cost:Number($('#cost',d).value),quantity:Number($('#quantity',d).value),low_stock_limit:Number($('#limit',d).value),category_id:$('#cat',d).value||null,is_active:$('#active',d).checked};p?await api.update('products','id=eq.'+p.id,v):await api.insert('products',[v]);toast('Produto salvo.','success');viewProdutos(root)})};
 $('#add').onclick=()=>form(null);$$('[data-edit]').forEach(b=>b.onclick=()=>form(rows.find(x=>x.id===b.dataset.edit)));$$('[data-stock]').forEach(b=>b.onclick=()=>{const p=rows.find(x=>x.id===b.dataset.stock);const d=dlg(`<form id="stockf"><h2>Estoque: ${esc(p.name)}</h2><label>Operação</label><select id="kind"><option value="in">Entrada</option><option value="out">Saída</option><option value="adjust">Ajuste (diferença)</option></select>${field('qty','Quantidade','number','1','step="1"')}${field('reason','Motivo')}<p class="err" id="err"></p><button class="btn" type="submit">Registrar</button></form>`);saveForm(d,'stockf',async()=>{await api.rpc('stock_move',{p_product:p.id,p_kind:$('#kind',d).value,p_qty:Number($('#qty',d).value),p_reason:$('#reason',d).value});toast('Estoque atualizado.','success');viewProdutos(root)})});
}

export async function viewDespesas(root){
 const rows=await api.select('expenses','select=*,expense_categories(name)&order=due_date.desc&limit=150');const cats=await api.select('expense_categories','select=*&is_active=eq.true&order=name');
 root.innerHTML=wrap('Despesas','<button class="btn" id="add">+ Despesa</button>',`<div class="stats"><div class="stat">Em aberto<b>${money(rows.filter(x=>x.status==='pending').reduce((a,x)=>a+Number(x.amount),0))}</b></div><div class="stat">Pagas<b>${money(rows.filter(x=>x.status==='paid').reduce((a,x)=>a+Number(x.amount),0))}</b></div></div><div class="card">${rows.map(x=>`<div class="svc"><div><b>${esc(x.description)}</b><br><span class="muted">${esc(x.expense_categories?.name||'Sem categoria')} · ${fmtDate(x.due_date)} · ${x.status==='paid'?'Paga':'Pendente'}</span><br>${money(x.amount)}</div><div class="row">${x.status==='pending'?`<button class="btn small" data-pay="${x.id}">Marcar paga</button>`:''}<button class="btn small ghost" data-del="${x.id}">Excluir</button></div></div>`).join('')||'Nenhuma despesa cadastrada.'}</div>`);
 $('#add').onclick=()=>{const d=dlg(`<form id="ef"><h2>Nova despesa</h2>${field('desc','Descrição')}${field('amount','Valor (R$)','number','','min="0.01" step="0.01"')}${field('date','Vencimento','date',new Date().toISOString().slice(0,10))}<label>Categoria</label><select id="cat">${cats.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select><p class="err" id="err"></p><button class="btn" type="submit">Salvar</button></form>`);saveForm(d,'ef',async()=>{await api.insert('expenses',[{description:$('#desc',d).value.trim(),amount:Number($('#amount',d).value),due_date:$('#date',d).value,category_id:$('#cat',d).value}]);toast('Despesa cadastrada.','success');viewDespesas(root)})};
 $$('[data-pay]').forEach(b=>b.onclick=()=>guard(async()=>{await api.update('expenses','id=eq.'+b.dataset.pay,{status:'paid',paid_at:new Date().toISOString(),method:'other'});viewDespesas(root)}));$$('[data-del]').forEach(b=>b.onclick=()=>guard(async()=>{if(await confirmBox('Excluir esta despesa?','Excluir')){await api.remove('expenses','id=eq.'+b.dataset.del);viewDespesas(root)}}));
}

export async function viewVendas(root){
 const [products,kits,sales]=await Promise.all([api.select('products','select=id,name,price,quantity&is_active=eq.true&order=name'),api.select('kits','select=id,name,price&is_active=eq.true&order=name'),api.select('sales','select=*,customers(full_name)&order=created_at.desc&limit=80')]);
 root.innerHTML=wrap('Vendas','<button class="btn" id="new">+ Registrar venda</button>',`<div class="card">${sales.map(s=>`<p><b>${money(s.total)}</b> · ${esc(s.customers?.full_name||'Consumidor')} · ${fmtDate(s.created_at)} · ${esc(s.method)} · ${s.status==='paid'?'Paga':'Estornada'}</p>`).join('')||'Nenhuma venda.'}</div>`);
 $('#new').onclick=()=>{const d=dlg(`<form id="saleform"><h2>Registrar venda</h2><label>Tipo de item</label><select id="type"><option value="product">Produto</option><option value="kit">Kit</option></select><label>Item</label><select id="item"></select>${field('qty','Quantidade','number','1','min="1" step="1"')}${field('discount','Desconto manual (R$)','number','0','min="0" step="0.01"')}${field('coupon','Cupom (opcional)')}<label>Pagamento</label><select id="method"><option value="pix">Pix</option><option value="cash">Dinheiro</option><option value="debit">Débito</option><option value="credit">Crédito</option><option value="other">Outro</option></select><p class="err" id="err"></p><button class="btn" type="submit">Finalizar venda</button></form>`);const fill=()=>{const type=$('#type',d).value;const arr=type==='product'?products:kits;$('#item',d).innerHTML=arr.map(p=>`<option value="${p.id}">${esc(p.name)} — ${money(p.price)}${type==='product'?' (estoque '+p.quantity+')':''}</option>`).join('')};$('#type',d).onchange=fill;fill();saveForm(d,'saleform',async()=>{const type=$('#type',d).value;await api.rpc('admin_register_sale',{p_items:[{type,id:$('#item',d).value,qty:Number($('#qty',d).value)}],p_method:$('#method',d).value,p_discount_kind:Number($('#discount',d).value)>0?'fixed':null,p_discount_amount:Number($('#discount',d).value),p_coupon:$('#coupon',d).value.trim()||null});toast('Venda registrada.','success');viewVendas(root)})};
}

export async function viewConteudo(root,table,title){
 const configs={gallery_items:{order:'published_at.desc',label:'Galeria',fields:['title','description','category','image_url'],status:'is_visible'},announcements:{order:'published_at.desc',label:'Avisos do site',fields:['title','body','image_url'],status:'status'},faq_items:{order:'sort_order',label:'Perguntas frequentes',fields:['question','answer'],status:'is_active'}};const c=configs[table];const rows=await api.select(table,'select=*&order='+c.order);
 root.innerHTML=wrap(title,'<button class="btn" id="add">+ Adicionar</button>',`<div class="card">${rows.map(r=>`<div class="svc"><div><b>${esc(r.title||r.question)}</b><br><span class="muted">${esc(r.body||r.answer||r.category||'')}</span></div><div class="row"><button class="btn small ghost" data-edit="${r.id}">Editar</button>${table==='announcements'&&r.status==='published'?`<button class="btn small ghost" data-notify="${r.id}">Avisar clientes</button>`:''}<button class="btn small ghost" data-del="${r.id}">Excluir</button></div></div>`).join('')||'Nenhum registro.'}</div>`);
 const form=r=>{const controls=c.fields.map(k=>field(k,k==='image_url'?'URL da imagem':k==='title'?'Título':k==='description'?'Descrição':k==='category'?'Categoria':k==='body'?'Texto':k==='question'?'Pergunta':'Resposta','text',r?.[k]||'',k==='title'||k==='question'||k==='image_url'?'required':'' )).join('');const d=dlg(`<form id="cf"><h2>${r?'Editar':'Adicionar'}</h2>${controls}${table==='announcements'?'<label>Status</label><select id="status"><option value="draft">Rascunho</option><option value="published">Publicado</option></select>':''}${table==='gallery_items'?'<label class="check"><input id="featured" type="checkbox"> Destaque</label>':''}${table==='faq_items'?field('sort_order','Ordem','number',r?.sort_order||0):''}<p class="err" id="err"></p><button class="btn" type="submit">Salvar</button></form>`);if(r&&table==='announcements')$('#status',d).value=r.status;if(r&&table==='gallery_items')$('#featured',d).checked=r.is_featured;saveForm(d,'cf',async()=>{const v={};c.fields.forEach(k=>v[k]=$('#'+k,d).value.trim());if(table==='announcements')v.status=$('#status',d).value;if(table==='gallery_items'){v.is_featured=$('#featured',d).checked;v.is_visible=true}if(table==='faq_items'){v.sort_order=Number($('#sort_order',d).value)||0;v.is_active=true}r?await api.update(table,'id=eq.'+r.id,v):await api.insert(table,[v]);toast('Salvo.','success');viewConteudo(root,table,title)})};
 $('#add').onclick=()=>form(null);$$('[data-edit]').forEach(b=>b.onclick=()=>form(rows.find(x=>x.id===b.dataset.edit)));$$('[data-del]').forEach(b=>b.onclick=()=>guard(async()=>{if(await confirmBox('Excluir este registro?','Excluir')){await api.remove(table,'id=eq.'+b.dataset.del);viewConteudo(root,table,title)}}));if(table==='announcements'){$$('[data-edit]').forEach(b=>{});$$('[data-notify]').forEach(b=>b.onclick=()=>guard(async()=>{const n=await api.rpc('admin_publish_announcement_notice',{p_id:b.dataset.notify});toast(`${n} cliente(s) notificado(s).`,'success')}))}
}

export async function viewAvaliacoes(root){
 const rows=await api.select('reviews','select=*&order=created_at.desc&limit=150');
 const avg=rows.length?rows.reduce((n,r)=>n+Number(r.rating),0)/rows.length:0;
 root.innerHTML=wrap('Avaliações',`<span class="badge">Média ${avg.toFixed(1)} · ${rows.length} avaliações</span>`,`<div class="stats"><div class="stat">Pendentes<b>${rows.filter(r=>r.status==='pending').length}</b></div><div class="stat">Publicadas<b>${rows.filter(r=>r.status==='approved').length}</b></div><div class="stat">Média geral<b>${avg.toFixed(1)} / 5</b></div></div><div class="card">${rows.map(r=>`<div class="svc"><div><b>${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)} · ${esc(r.display_name||'Cliente')}</b><p>${esc(r.comment||'Sem comentário')}</p><span class="muted">${fmtDate(r.created_at)} · ${({pending:'Aguardando aprovação',approved:'Publicada',rejected:'Rejeitada',hidden:'Oculta'})[r.status]||esc(r.status)}</span></div><select data-status="${r.id}"><option value="pending">Pendente</option><option value="approved">Aprovar e publicar</option><option value="rejected">Rejeitar</option><option value="hidden">Ocultar</option></select></div>`).join('')||'Nenhuma avaliação recebida.'}</div>`);
 $$('[data-status]').forEach(sel=>{sel.value=rows.find(r=>r.id===sel.dataset.status).status;sel.onchange=()=>guard(async()=>{await api.update('reviews','id=eq.'+sel.dataset.status,{status:sel.value});toast('Avaliação atualizada.','success');await viewAvaliacoes(root)})});
}

export async function viewTarefas(root){const rows=await api.select('tasks','select=*&order=due_at.asc.nullslast');root.innerHTML=wrap('Tarefas','<button class="btn" id="add">+ Tarefa</button>',`<div class="card">${rows.map(r=>`<div class="svc"><div><b>${esc(r.title)}</b><br><span class="muted">${esc(r.priority)} · ${esc(r.status)} ${r.due_at?'· '+fmtDate(r.due_at):''}</span><p>${esc(r.description||'')}</p></div><select data-task="${r.id}"><option value="pendente">Pendente</option><option value="em_andamento">Em andamento</option><option value="concluida">Concluída</option></select></div>`).join('')||'Nenhuma tarefa.'}</div>`);$('#add').onclick=()=>{const d=dlg(`<form id="tf"><h2>Nova tarefa</h2>${field('title','Título')}${field('description','Descrição')} ${field('due','Prazo','datetime-local')}<label>Prioridade</label><select id="priority"><option>baixa</option><option selected>media</option><option>alta</option></select><p class="err" id="err"></p><button class="btn" type="submit">Salvar</button></form>`);saveForm(d,'tf',async()=>{await api.insert('tasks',[{title:$('#title',d).value.trim(),description:$('#description',d).value,due_at:$('#due',d).value?new Date($('#due',d).value).toISOString():null,priority:$('#priority',d).value}]);viewTarefas(root)})};$$('[data-task]').forEach(s=>{s.value=rows.find(r=>r.id===s.dataset.task).status;s.onchange=()=>guard(async()=>api.update('tasks','id=eq.'+s.dataset.task,{status:s.value}))})}

export async function viewMetas(root){
 const rows=await api.select('goals','select=*&order=period,metric');
 const today=new Date().toLocaleDateString('en-CA',{timeZone:'America/Recife'});
 const range=g=>{if(g.start_date&&g.end_date)return [g.start_date,g.end_date];const period=g.period;if(period==='day')return [today,today];if(period==='week'){const d=new Date(today+'T12:00:00-03:00');const day=(d.getDay()+6)%7;const start=new Date(d);start.setDate(d.getDate()-day);return [start.toLocaleDateString('en-CA'),today]}return [today.slice(0,8)+'01',today]};
 const labelMetric={revenue:'Faturamento',profit:'Lucro estimado',product_qty:'Produtos vendidos',product_revenue:'Faturamento de produtos'};
 const labelPeriod={day:'Diária',week:'Semanal',month:'Mensal'};
 const progress=async g=>{const [a,b]=range(g);const r=await api.rpc('report_summary',{p_from:a,p_to:b});return Number(r[g.metric]||0)};
 const values=await Promise.all(rows.map(async g=>({g,current:await progress(g).catch(()=>0)})));
 root.innerHTML=wrap('Metas','<button class="btn" id="add">+ Nova meta</button>',`<div class="grid">${values.map(({g,current})=>{const pct=g.target>0?Math.min(100,current/g.target*100):0;return `<article class="card"><div class="row" style="justify-content:space-between"><b>${esc(g.title||labelMetric[g.metric]||g.metric)}</b><span class="badge">${labelPeriod[g.period]||g.period}</span></div><p class="muted">${esc(g.description||labelMetric[g.metric]||'Meta de desempenho')}${g.responsible?' · Responsável: '+esc(g.responsible):''}</p><div class="stats"><div class="stat">Realizado<b>${g.metric==='product_qty'?current:money(current)}</b></div><div class="stat">Objetivo<b>${g.metric==='product_qty'?g.target:money(g.target)}</b></div></div><div class="progress"><span style="width:${pct.toFixed(1)}%"></span></div><p class="hint">${pct.toFixed(1)}% alcançado · ${Math.max(0,Number(g.target)-current).toFixed(g.metric==='product_qty'?0:2)} restante</p><button class="btn small ghost" data-edit="${g.id}">Editar detalhes</button></article>`}).join('')||'<div class="notice">Nenhuma meta cadastrada.</div>'}</div>`);
 const form=async old=>{const d=dlg(`<form id="gf"><h2>${old?'Editar meta':'Nova meta'}</h2>${field('title','Nome da meta','text',old?.title||'')}<label>Período</label><select id="period"><option value="day">Diária</option><option value="week">Semanal</option><option value="month">Mensal</option></select><label>Indicador</label><select id="metric"><option value="revenue">Faturamento (R$)</option><option value="profit">Lucro estimado (R$)</option><option value="product_qty">Quantidade de produtos</option><option value="product_revenue">Faturamento de produtos (R$)</option></select>${field('target','Valor desejado','number',old?.target??'','min="0" step="0.01" required')}${field('responsible','Responsável','text',old?.responsible||'')}${field('start','Início personalizado','date',old?.start_date||'')}${field('end','Fim personalizado','date',old?.end_date||'')}<label for="description">Descrição e plano de ação</label><textarea id="description" rows="4">${esc(old?.description||'')}</textarea><p class="hint">O progresso é calculado a partir dos dados reais de vendas, pagamentos e atendimentos do período.</p><p class="err" id="err"></p><button class="btn" type="submit">Salvar meta</button></form>`);
 $('#period',d).value=old?.period||'month';$('#metric',d).value=old?.metric||'revenue';
 saveForm(d,'gf',async()=>{const row={title:$('#title',d).value.trim()||null,period:$('#period',d).value,metric:$('#metric',d).value,target:Number($('#target',d).value),responsible:$('#responsible',d).value.trim()||null,start_date:$('#start',d).value||null,end_date:$('#end',d).value||null,description:$('#description',d).value.trim()||null};const same=rows.find(x=>x.period===row.period&&x.metric===row.metric&&x.id!==old?.id);if(same)throw new Error('Já existe uma meta para esse indicador e período. Edite a meta existente.');old?await api.update('goals','id=eq.'+old.id,row):await api.insert('goals',[row]);toast('Meta salva.','success');await viewMetas(root)});};
 $('#add').onclick=()=>form(null);$$('[data-edit]').forEach(b=>b.onclick=()=>form(rows.find(x=>x.id===b.dataset.edit)));
}

export async function viewCampanhas(root){
 const rows=await api.select('campaigns','select=*&order=created_at.desc');
 const recipients=rows.length?await api.select('campaign_recipients','select=*,customers(full_name,whatsapp,marketing_opt_in)&order=updated_at.desc').catch(()=>[]):[];
 const active=rows.find(r=>r.id===new URLSearchParams(location.hash.split('?')[1]||'').get('campaign'))||rows[0]||null;
 root.innerHTML=wrap('Campanhas','<button class="btn" id="add">+ Nova campanha</button>',`<div class="grid">${rows.map(r=>{const rs=recipients.filter(x=>x.campaign_id===r.id);return `<article class="card"><div class="row" style="justify-content:space-between"><b>${esc(r.name)}</b><span class="badge">${({draft:'Rascunho',prepared:'Público preparado',finished:'Finalizada'})[r.status]||r.status}</span></div><p class="muted">${esc(r.objective||'Sem objetivo definido')} · ${esc(r.segment||'Todos')}</p><p>${esc(r.message||'Sem mensagem')}</p><div class="stats"><div class="stat">Público<b>${rs.length}</b></div><div class="stat">Enviadas manualmente<b>${rs.filter(x=>x.status==='sent_manual').length}</b></div></div><button class="btn small" data-open="${r.id}">Gerenciar campanha</button></article>`}).join('')||'<div class="notice">Nenhuma campanha criada.</div>'}</div>`);
 const show=async id=>{const c=rows.find(x=>x.id===id);if(!c)return;let rs=recipients.filter(x=>x.campaign_id===id);const d=dlg(`<h2>${esc(c.name)}</h2><p class="muted">${esc(c.objective||'')} · ${esc(c.description||'')}</p><div class="row"><button class="btn small" id="prepare">Preparar público</button><button class="btn small ghost" id="finish">Finalizar campanha</button></div><p class="hint">Somente clientes que autorizaram receber novidades entram no público. O WhatsApp será aberto para envio manual individual; não há disparo automático.</p><div id="campstats" class="stats"></div><div id="recipients" class="card"></div><button class="btn ghost" data-close>Fechar</button>`);
 const paint=()=>{const counts={prepared:rs.filter(x=>x.status==='prepared').length,opened:rs.filter(x=>x.status==='opened').length,sent_manual:rs.filter(x=>x.status==='sent_manual').length,responded:rs.filter(x=>x.status==='responded').length,skipped:rs.filter(x=>x.status==='skipped').length};$('#campstats',d).innerHTML=Object.entries(counts).map(([k,v])=>`<div class="stat">${({prepared:'Preparados',opened:'WhatsApp aberto',sent_manual:'Enviados',responded:'Responderam',skipped:'Ignorados'})[k]}<b>${v}</b></div>`).join('');$('#recipients',d).innerHTML=rs.map(x=>`<div class="svc"><div><b>${esc(x.customers?.full_name||'Cliente')}</b><br><span class="muted">${esc(x.customers?.whatsapp||'Sem WhatsApp')} · ${({prepared:'Preparado',opened:'WhatsApp aberto',sent_manual:'Enviado manualmente',responded:'Respondeu',skipped:'Ignorado'})[x.status]||x.status}</span>${x.result_note?`<br>${esc(x.result_note)}`:''}</div><div class="row">${x.customers?.whatsapp?`<button class="btn small" data-send="${x.id}">Abrir WhatsApp</button>`:''}<select data-recipient="${x.id}"><option value="prepared">Preparado</option><option value="opened">WhatsApp aberto</option><option value="sent_manual">Enviado</option><option value="responded">Respondeu</option><option value="skipped">Ignorado</option></select></div></div>`).join('')||'Público ainda não preparado.';$$('[data-recipient]',d).forEach(s=>{s.value=rs.find(x=>x.id===s.dataset.recipient).status;s.onchange=async()=>{await api.update('campaign_recipients','id=eq.'+s.dataset.recipient,{status:s.value,updated_at:new Date().toISOString()});rs=await api.select('campaign_recipients','select=*,customers(full_name,whatsapp,marketing_opt_in)&campaign_id=eq.'+id+'&order=updated_at.desc');paint()}});$$('[data-send]',d).forEach(b=>b.onclick=()=>{const r=rs.find(x=>x.id===b.dataset.send);const phone=onlyDigits(r.customers?.whatsapp||'');if(phone.length<10)return toast('Cliente sem WhatsApp válido.','error');const url='https://wa.me/55'+phone.slice(-11)+'?text='+encodeURIComponent(c.message||'Olá! Temos uma novidade na Barbearia do Charley.');window.open(url,'_blank','noopener');api.update('campaign_recipients','id=eq.'+r.id,{status:'opened',updated_at:new Date().toISOString()}).then(async()=>{rs=await api.select('campaign_recipients','select=*,customers(full_name,whatsapp,marketing_opt_in)&campaign_id=eq.'+id+'&order=updated_at.desc');paint()}).catch(e=>toast(e.message,'error'))})};paint();
 $('#prepare',d).onclick=async()=>{try{const n=await api.rpc('admin_prepare_campaign',{p_campaign:id});rs=await api.select('campaign_recipients','select=*,customers(full_name,whatsapp,marketing_opt_in)&campaign_id=eq.'+id+'&order=updated_at.desc');toast(`${n} clientes preparados.`,'success');paint()}catch(e){toast(e.message,'error')}};
 $('#finish',d).onclick=async()=>{try{await api.update('campaigns','id=eq.'+id,{status:'finished'});toast('Campanha finalizada.','success');d.close();await viewCampanhas(root)}catch(e){toast(e.message,'error')}};
 };
 $$('[data-open]').forEach(b=>b.onclick=()=>show(b.dataset.open));
 $('#add').onclick=()=>{const d=dlg(`<form id="campf"><h2>Nova campanha</h2>${field('name','Nome da campanha','text','','required')}${field('objective','Objetivo','text','')}${field('description','Descrição interna','text','')}<label>Segmento de clientes</label><select id="segment"><option value="all_optin">Todos que aceitaram receber mensagens</option><option value="new_customers">Clientes novos (últimos 30 dias)</option><option value="inactive_30">Sem visitar há 30 dias ou mais</option><option value="frequent">Clientes frequentes (3+ visitas)</option><option value="subscribers">Clientes com plano ativo</option></select>${field('starts','Início','date')}${field('ends','Fim','date')}<label for="message">Mensagem para WhatsApp</label><textarea id="message" rows="5" required></textarea><p class="hint">O envio é individual e manual pelo WhatsApp. O sistema registra o andamento.</p><p class="err" id="err"></p><button class="btn" type="submit">Salvar campanha</button></form>`);saveForm(d,'campf',async()=>{await api.insert('campaigns',[{name:$('#name',d).value.trim(),objective:$('#objective',d).value.trim()||null,description:$('#description',d).value.trim()||null,segment:$('#segment',d).value,starts_at:$('#starts',d).value||null,ends_at:$('#ends',d).value||null,message:$('#message',d).value.trim(),status:'draft'}]);toast('Campanha criada.','success');await viewCampanhas(root)})};
}

export async function viewRelatorios(root){
 const today=new Date().toLocaleDateString('en-CA',{timeZone:'America/Recife'}),from=today.slice(0,8)+'01';
 root.innerHTML=wrap('Relatórios','',`<div class="card"><div class="row"><div>${field('from','De','date',from)}</div><div>${field('to','Até','date',today)}</div><button class="btn" id="run">Gerar relatório completo</button></div><div id="report"><p class="muted">Selecione o período e gere o relatório.</p></div></div>`);
 $('#run').onclick=()=>guard(async()=>{const a=$('#from').value,b=$('#to').value;if(!a||!b||a>b)throw new Error('Informe um período válido.');$('#report').innerHTML='<p class="loading">Consolidando pagamentos, despesas, atendimentos, produtos e assinaturas…</p>';const r=await api.rpc('report_summary',{p_from:a,p_to:b});const fromIso=new Date(a+'T00:00:00-03:00').toISOString(),toIso=new Date(new Date(b+'T00:00:00-03:00').getTime()+86400000).toISOString();const [payments,expenses,appointments,sales]=await Promise.all([api.select('payments',`select=id,amount,method,kind,paid_at,appointment_id,sale_id,subscription_id&paid_at=gte.${encodeURIComponent(fromIso)}&paid_at=lt.${encodeURIComponent(toIso)}&order=paid_at&limit=1000`).catch(()=>[]),api.select('expenses',`select=*,expense_categories(name)&status=eq.paid&paid_at=gte.${encodeURIComponent(fromIso)}&paid_at=lt.${encodeURIComponent(toIso)}&order=paid_at&limit=1000`).catch(()=>[]),api.select('appointments',`select=id,start_at,status,guest_name,guest_whatsapp,final_total,estimated_total,appointment_items(service_name,price_final)&start_at=gte.${encodeURIComponent(fromIso)}&start_at=lt.${encodeURIComponent(toIso)}&order=start_at&limit=1000`).catch(()=>[]),api.select('sales',`select=id,total,method,status,created_at,sale_items(name,qty,unit_price_final)&created_at=gte.${encodeURIComponent(fromIso)}&created_at=lt.${encodeURIComponent(toIso)}&order=created_at&limit=1000`).catch(()=>[])]);const methodNames={pix:'Pix',cash:'Dinheiro',debit:'Débito',credit:'Crédito',other:'Outro'},kindNames={service:'Serviços',product:'Produtos',subscription:'Assinaturas'};const lines=[['Relatório Barbearia do Charley',`${a} a ${b}`],['Indicador','Valor'],['Faturamento',r.revenue],['Despesas pagas',r.expenses],['Resultado',r.profit],['Ticket médio',r.avg_ticket],['Novos clientes',r.new_customers],['Produtos vendidos',r.products_qty],['Receita de produtos',r.products_revenue],['Atendimentos',r.appointments?.total||0],['Concluídos',r.appointments?.completed||0],['Aguardando/confirmados',r.appointments?.open||0],['Cancelados',r.appointments?.cancelled||0],['Faltas',r.appointments?.no_show||0],[],['Receita por forma de pagamento','Valor'],...Object.entries(r.by_method||{}).map(([k,v])=>[methodNames[k]||k,v]),[],['Receita por tipo','Valor'],...Object.entries(r.by_kind||{}).map(([k,v])=>[kindNames[k]||k,v]),[],['Despesas por categoria','Valor'],...Object.entries(r.expenses_by_category||{}).map(([k,v])=>[k,v]),[],['Serviços mais realizados','Quantidade','Receita'],...(r.top_services||[]).map(x=>[x.name,x.qty,x.revenue]),[],['Produtos mais vendidos','Quantidade','Receita','Margem'],...(r.products||[]).map(x=>[x.name,x.qty,x.revenue,x.margin]),[],['Assinaturas','Quantidade'],...Object.entries(r.subs||{}).filter(([k,v])=>typeof v==='number').map(([k,v])=>[k,v]),['Assinaturas por plano','Quantidade'],...Object.entries(r.subs?.by_plan||{}).map(([k,v])=>[k,v]),[],['LANÇAMENTOS DE PAGAMENTO','Valor','Forma','Tipo','Data'],...payments.map(x=>[x.id,x.amount,methodNames[x.method]||x.method,kindNames[x.kind]||x.kind,x.paid_at]),[],['DESPESAS PAGAS','Descrição','Categoria','Valor','Status','Data do pagamento'],...expenses.map(x=>[x.description,x.expense_categories?.name||'Sem categoria',x.amount,x.status,x.paid_at]),[],['AGENDAMENTOS','Cliente','Status','Data','Total'],...appointments.map(x=>[x.guest_name||'Cliente',x.status,x.start_at,x.final_total??x.estimated_total]),[],['VENDAS','Total','Forma','Status','Data'],...sales.map(x=>[x.total,methodNames[x.method]||x.method,x.status,x.created_at])];
 $('#report').innerHTML=`<div class="stats"><div class="stat">Faturamento<b>${money(r.revenue)}</b></div><div class="stat">Despesas pagas<b>${money(r.expenses)}</b></div><div class="stat">Resultado<b>${money(r.profit)}</b></div><div class="stat">Ticket médio<b>${money(r.avg_ticket)}</b></div><div class="stat">Novos clientes<b>${r.new_customers||0}</b></div><div class="stat">Produtos vendidos<b>${r.products_qty||0}</b></div></div><h3>Atendimentos</h3><div class="stats"><div class="stat">Total<b>${r.appointments?.total||0}</b></div><div class="stat">Concluídos<b>${r.appointments?.completed||0}</b></div><div class="stat">Em aberto<b>${r.appointments?.open||0}</b></div><div class="stat">Cancelados<b>${r.appointments?.cancelled||0}</b></div><div class="stat">Faltas<b>${r.appointments?.no_show||0}</b></div></div><h3>Receita por forma de pagamento</h3>${Object.entries(r.by_method||{}).map(([k,v])=>`<p>${methodNames[k]||esc(k)}: <b>${money(v)}</b></p>`).join('')||'Sem pagamentos no período.'}<h3>Despesas por categoria</h3>${Object.entries(r.expenses_by_category||{}).map(([k,v])=>`<p>${esc(k)}: <b>${money(v)}</b></p>`).join('')||'Sem despesas pagas.'}<h3>Serviços mais realizados</h3>${(r.top_services||[]).map(x=>`<p>${esc(x.name)} · ${x.qty} atendimentos · ${money(x.revenue)} · média ${x.avg_min||0} min</p>`).join('')||'Sem atendimentos concluídos.'}<h3>Produtos mais vendidos</h3>${(r.products||[]).map(x=>`<p>${esc(x.name)} · ${x.qty} un. · Receita ${money(x.revenue)} · Margem ${money(x.margin)}</p>`).join('')||'Sem vendas de produtos.'}<h3>Assinaturas</h3><p>Ativas: ${r.subs?.active||0} · Em atraso: ${r.subs?.past_due||0} · Pendentes: ${r.subs?.pending||0} · MRR: ${money(r.subs?.mrr||0)} · Receita no período: ${money(r.subs?.revenue||0)}</p><h3>Lançamentos detalhados</h3><p>${payments.length} pagamentos · ${expenses.length} despesas · ${appointments.length} agendamentos · ${sales.length} vendas no período.</p><details><summary>Ver pagamentos (${payments.length})</summary>${payments.map(x=>`<p>${fmtDate(x.paid_at)} ${fmtTime(x.paid_at)} · ${esc(kindNames[x.kind]||x.kind)} · ${esc(methodNames[x.method]||x.method)} · <b>${money(x.amount)}</b></p>`).join('')||'Sem pagamentos.'}</details><details><summary>Ver despesas (${expenses.length})</summary>${expenses.map(x=>`<p>${esc(x.description)} · ${esc(x.expense_categories?.name||'Sem categoria')} · ${esc(x.status)} · ${money(x.amount)}</p>`).join('')||'Sem despesas.'}</details><details><summary>Ver agendamentos (${appointments.length})</summary>${appointments.map(x=>`<p>${fmtDate(x.start_at)} ${fmtTime(x.start_at)} · ${esc(x.guest_name||'Cliente')} · ${esc(x.status)} · ${money(x.final_total??x.estimated_total)}</p>`).join('')||'Sem agendamentos.'}</details><details><summary>Ver vendas (${sales.length})</summary>${sales.map(x=>`<p>${fmtDate(x.created_at)} · ${money(x.total)} · ${esc(methodNames[x.method]||x.method)} · ${esc(x.status)}</p>`).join('')||'Sem vendas.'}</details><button class="btn" id="csv">Exportar relatório detalhado CSV</button>`;
 $('#csv').onclick=()=>{const csv=lines.map(row=>row.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(';')).join('\r\n');const blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'});const u=URL.createObjectURL(blob);const link=document.createElement('a');link.href=u;link.download=`relatorio-completo-${a}-${b}.csv`;link.click();setTimeout(()=>URL.revokeObjectURL(u),1500)};
 });$('#run').click();
}

export async function viewAssinaturas(root){
 const [rows,customers,plans]=await Promise.all([api.select('subscriptions','select=*,customers(full_name,whatsapp),plans(name)&order=created_at.desc&limit=300'),api.select('customers','select=id,full_name,whatsapp,is_active&is_active=eq.true&order=full_name&limit=500'),api.select('plans','select=id,name,price,is_active&is_active=eq.true&order=name')]);
 const names={pending:'Aguardando pagamento',active:'Ativa',past_due:'Em atraso',suspended:'Suspensa',cancel_requested:'Cancelamento solicitado',cancelling:'Cancelamento agendado',cancelled:'Cancelada'};
 root.innerHTML=wrap('Assinaturas','<button class="btn" id="add">+ Vincular cliente a um plano</button>',`<div class="stats"><div class="stat">Ativas<b>${rows.filter(x=>x.status==='active').length}</b></div><div class="stat">Pendentes<b>${rows.filter(x=>x.status==='pending').length}</b></div><div class="stat">Em atraso<b>${rows.filter(x=>x.status==='past_due').length}</b></div><div class="stat">Receita mensal prevista<b>${money(rows.filter(x=>['active','cancel_requested','cancelling'].includes(x.status)).reduce((n,x)=>n+Number(x.price),0))}</b></div></div><div class="card">${rows.map(r=>`<div class="svc"><div><b>${esc(r.customers?.full_name||'Cliente')}</b> · ${esc(r.plans?.name||'Plano')}<br><span class="muted">${names[r.status]||esc(r.status)} · ${money(r.price)} · Ciclo até ${r.cycle_end||'não iniciado'}</span>${r.customers?.whatsapp?`<br><a target="_blank" rel="noopener" href="https://wa.me/55${onlyDigits(r.customers.whatsapp).slice(-11)}">${esc(r.customers.whatsapp)}</a>`:''}</div><div class="row">${r.status==='pending'?`<button class="btn small" data-activate="${r.id}">Confirmar pagamento e ativar</button>`:''}${['past_due','suspended','active'].includes(r.status)?`<select data-sub="${r.id}"><option value="active">Ativa</option><option value="past_due">Em atraso</option><option value="suspended">Suspensa</option></select>`:''}${['cancel_requested','cancelling'].includes(r.status)?`<button class="btn small ghost" data-cancel="${r.id}">Confirmar cancelamento</button>`:''}${['active','past_due','suspended'].includes(r.status)?`<button class="btn small ghost" data-renew="${r.id}">Registrar renovação</button>`:''}</div></div>`).join('')||'Nenhuma assinatura cadastrada.'}</div>`);
 $('#add').onclick=()=>{const d=dlg(`<form id="subf"><h2>Vincular cliente a um plano</h2><label>Cliente</label><select id="customer" required><option value="">Selecione um cliente</option>${customers.map(c=>`<option value="${c.id}">${esc(c.full_name)} · ${esc(c.whatsapp||'sem WhatsApp')}</option>`).join('')}</select><label>Plano</label><select id="plan" required><option value="">Selecione um plano</option>${plans.map(p=>`<option value="${p.id}">${esc(p.name)} · ${money(p.price)}</option>`).join('')}</select><label>Ativação</label><select id="activate"><option value="false">Criar como pendente de pagamento</option><option value="true">Pagamento já recebido — ativar agora</option></select><label>Forma de pagamento</label><select id="method"><option value="pix">Pix</option><option value="cash">Dinheiro</option><option value="debit">Débito</option><option value="credit">Crédito</option><option value="other">Outro</option></select>${field('note','Observação interna','text','')}<p class="hint">Ao ativar, o sistema registra o pagamento e gera os créditos do primeiro ciclo de 30 dias.</p><p class="err" id="err"></p><button class="btn" type="submit">Salvar assinatura</button></form>`);saveForm(d,'subf',async()=>{await api.rpc('admin_create_subscription',{p_customer:$('#customer',d).value,p_plan:$('#plan',d).value,p_activate:$('#activate',d).value==='true',p_method:$('#method',d).value,p_note:$('#note',d).value.trim()||null});toast('Cliente vinculado ao plano.','success');await viewAssinaturas(root)})};
 $$('[data-sub]').forEach(sel=>{sel.value=rows.find(r=>r.id===sel.dataset.sub).status;sel.onchange=()=>guard(async()=>{await api.rpc('admin_set_subscription_status',{p_sub:sel.dataset.sub,p_status:sel.value});toast('Status atualizado.','success');await viewAssinaturas(root)})});
 const methodDialog=(title,fn)=>{const d=dlg(`<form id="rf"><h2>${title}</h2><label>Pagamento</label><select id="method"><option value="pix">Pix</option><option value="cash">Dinheiro</option><option value="debit">Débito</option><option value="credit">Crédito</option><option value="other">Outro</option></select><p class="err" id="err"></p><button class="btn" type="submit">Confirmar</button></form>`);saveForm(d,'rf',async()=>{await fn($('#method',d).value);toast('Operação registrada.','success');await viewAssinaturas(root)})};
 $$('[data-activate]').forEach(b=>b.onclick=()=>methodDialog('Confirmar pagamento e ativar',m=>api.rpc('admin_activate_subscription',{p_sub:b.dataset.activate,p_method:m})));$$('[data-renew]').forEach(b=>b.onclick=()=>methodDialog('Registrar renovação',m=>api.rpc('admin_renew_subscription',{p_sub:b.dataset.renew,p_method:m})));$$('[data-cancel]').forEach(b=>b.onclick=()=>guard(async()=>{if(await confirmBox('Confirmar o cancelamento desta assinatura?','Cancelar assinatura')){await api.rpc('admin_confirm_cancel',{p_sub:b.dataset.cancel});await viewAssinaturas(root)}}));
}

export async function viewPlanos(root){const [plans,services]=await Promise.all([api.select('plans','select=*&order=name'),api.select('services','select=id,name&is_active=eq.true&order=sort_order')]);root.innerHTML=wrap('Planos','<button class="btn" id="add">+ Plano</button>',`<div class="card">${plans.map(p=>`<div class="svc"><div><b>${esc(p.name)}</b><br>${money(p.price)} · ${p.is_active?'Ativo':'Inativo'}</div><button class="btn small ghost" data-edit="${p.id}">Editar</button></div>`).join('')||'Nenhum plano.'}</div>`);const form=async p=>{const items=p?await api.select('plan_items','select=*&plan_id=eq.'+p.id):[];const d=dlg(`<form id="plf"><h2>${p?'Editar':'Novo'} plano</h2>${field('name','Nome','text',p?.name)}${field('description','Descrição','text',p?.description)}${field('price','Preço mensal (R$)','number',p?.price??'','min="0" step="0.01"')}${field('max','Limite de assinantes (opcional)','number',p?.max_subscribers??'','min="1"')}<label class="check"><input id="active" type="checkbox" ${p?.is_active===false?'':'checked'}> Ativo</label><h3>Créditos incluídos por ciclo de 30 dias</h3>${services.map(s=>{const it=items.find(x=>x.service_id===s.id);return `<label class="check"><input type="checkbox" data-service="${s.id}" ${it?'checked':''}> ${esc(s.name)} <input aria-label="Quantidade de ${esc(s.name)}" data-qty="${s.id}" type="number" min="1" value="${it?.quantity||1}" style="width:80px"></label>`}).join('')}<p class="err" id="err"></p><button class="btn" type="submit">Salvar plano e créditos</button></form>`);saveForm(d,'plf',async()=>{const v={name:$('#name',d).value.trim(),description:$('#description',d).value,price:Number($('#price',d).value),max_subscribers:$('#max',d).value?Number($('#max',d).value):null,is_active:$('#active',d).checked};let id=p?.id;if(p)await api.update('plans','id=eq.'+id,v);else{id=(await api.insert('plans',[v]))[0].id}const chosen=$$('[data-service]:checked',d).map(x=>({plan_id:id,service_id:x.dataset.service,quantity:Math.max(1,Number($(`[data-qty="${x.dataset.service}"]`,d).value)||1)}));await api.remove('plan_items','plan_id=eq.'+id);if(chosen.length)await api.insert('plan_items',chosen);toast('Plano e créditos salvos.','success');viewPlanos(root)})};$('#add').onclick=()=>form(null);$$('[data-edit]').forEach(b=>b.onclick=()=>form(plans.find(p=>p.id===b.dataset.edit)))}

export async function viewCupons(root){const rows=await api.select('coupons','select=*&order=created_at.desc');root.innerHTML=wrap('Cupons','<button class="btn" id="add">+ Cupom</button>',`<div class="card">${rows.map(c=>`<div class="svc"><div><b>${esc(c.code)}</b><br>${c.kind==='percent'?c.amount+'%':money(c.amount)} · ${c.is_active?'Ativo':'Inativo'} · ${esc(c.applies_to)}</div><button class="btn small ghost" data-toggle="${c.id}" data-active="${c.is_active}">${c.is_active?'Desativar':'Ativar'}</button></div>`).join('')||'Nenhum cupom.'}</div>`);$('#add').onclick=()=>{const d=dlg(`<form id="couponf"><h2>Novo cupom</h2>${field('code','Código') }<label>Tipo</label><select id="kind"><option value="percent">Percentual (%)</option><option value="fixed">Valor fixo (R$)</option></select>${field('amount','Desconto','number','','min="0.01" step="0.01"')}${field('min','Compra mínima (R$)','number','0','min="0" step="0.01"')}${field('max','Limite total de usos (opcional)','number','','min="1"')}<label>Aplicação</label><select id="scope"><option value="all">Tudo</option><option value="services">Serviços</option><option value="products">Produtos</option></select><p class="err" id="err"></p><button class="btn" type="submit">Criar cupom</button></form>`);saveForm(d,'couponf',async()=>{await api.insert('coupons',[{code:$('#code',d).value.trim().toUpperCase(),kind:$('#kind',d).value,amount:Number($('#amount',d).value),min_purchase:Number($('#min',d).value),max_uses:$('#max',d).value?Number($('#max',d).value):null,applies_to:$('#scope',d).value}]);viewCupons(root)})};$$('[data-toggle]').forEach(b=>b.onclick=()=>guard(async()=>{await api.update('coupons','id=eq.'+b.dataset.toggle,{is_active:b.dataset.active!=='true'});viewCupons(root)}))}

export async function viewPrivacidade(root){
 const rows=await api.select('privacy_requests','select=*,profiles(full_name,whatsapp,email)&order=created_at.desc');
 const kinds={access:'Acesso aos dados',correction:'Correção de dados',deletion:'Exclusão / anonimização'};
 root.innerHTML=wrap('Solicitações LGPD','',`<div class="stats"><div class="stat">Abertas<b>${rows.filter(x=>x.status==='open').length}</b></div><div class="stat">Concluídas<b>${rows.filter(x=>x.status==='done').length}</b></div><div class="stat">Recusadas<b>${rows.filter(x=>x.status==='rejected').length}</b></div></div><div class="card">${rows.map(r=>`<article class="svc"><div style="flex:1"><b>${esc(kinds[r.kind]||r.kind)}</b><br><span class="muted">${esc(r.profiles?.full_name||r.contact||'Contato não identificado')} · ${fmtDate(r.created_at)} · ${({open:'Em aberto',done:'Concluída',rejected:'Recusada'})[r.status]||r.status}</span>${r.profiles?.whatsapp?`<br>WhatsApp: ${esc(r.profiles.whatsapp)}`:''}${r.profiles?.email?`<br>E-mail: ${esc(r.profiles.email)}`:''}<p><b>Detalhes informados:</b><br>${esc(r.details||'Nenhum detalhe adicional informado.')}</p><p class="hint">${r.kind==='access'?'O titular solicita confirmação e acesso aos dados pessoais tratados pela barbearia. Consulte o cadastro, histórico de agendamentos, pagamentos e comunicações antes de responder.':r.kind==='correction'?'O titular solicita correção de dados. Confira a informação indicada e atualize o cadastro do cliente antes de concluir.':'O titular solicita exclusão. Quando aplicável, use anonimização para preservar registros financeiros e obrigações legais.'}</p></div><div class="row">${r.status==='open'?`<button class="btn small" data-done="${r.id}">Marcar concluída</button><button class="btn small ghost" data-reject="${r.id}">Recusar</button>${r.kind==='deletion'?`<button class="btn small danger" data-anon="${r.id}">Anonimizar dados</button>`:''}`:''}</div></article>`).join('')||'Nenhuma solicitação recebida.'}</div>`);
 $$('[data-done]').forEach(b=>b.onclick=()=>guard(async()=>{await api.rpc('admin_process_privacy_request',{p_request:b.dataset.done,p_action:'complete'});toast('Solicitação marcada como concluída.','success');await viewPrivacidade(root)}));
 $$('[data-reject]').forEach(b=>b.onclick=()=>guard(async()=>{if(await confirmBox('Registrar a recusa desta solicitação? Inclua a justificativa no atendimento ao titular.','Registrar recusa')){await api.rpc('admin_process_privacy_request',{p_request:b.dataset.reject,p_action:'reject'});await viewPrivacidade(root)}}));
 $$('[data-anon]').forEach(b=>b.onclick=()=>guard(async()=>{if(await confirmBox('Atenção: isso anonimiza os dados pessoais do cliente e pode excluir sua conta de acesso. Os registros financeiros são preservados quando possível. Deseja continuar?','Anonimizar dados')){await api.rpc('admin_process_privacy_request',{p_request:b.dataset.anon,p_action:'anonymize'});toast('Processamento de anonimização concluído.','success');await viewPrivacidade(root)}}));
}

export async function viewListaEspera(root){
 const date=new Date().toLocaleDateString('en-CA',{timeZone:'America/Recife'});let rows=[];
 try{rows=await api.rpc('admin_waitlist_list')}catch(e){root.innerHTML=wrap('Lista de espera','',`<div class="notice error">${esc(e.message)}<p>Execute o arquivo PATCH-V6.sql incluído no pacote para habilitar o painel da lista de espera.</p></div>`);return}
 const services=await api.select('services','select=id,name').catch(()=>[]);const names=Object.fromEntries(services.map(s=>[s.id,s.name]));
 root.innerHTML=wrap('Lista de espera',`<div class="row"><input type="date" id="wdate" value="${date}"><button class="btn" id="process">Procurar horário disponível</button><button class="btn ghost" id="reload">Atualizar</button></div>`,`<div class="stats"><div class="stat">Aguardando<b>${rows.filter(x=>x.status==='active').length}</b></div><div class="stat">Convite enviado<b>${rows.filter(x=>x.status==='notified').length}</b></div><div class="stat">Agendados<b>${rows.filter(x=>x.status==='booked').length}</b></div></div><div class="card">${rows.map(w=>`<div class="svc"><div><b>${esc(w.full_name||'Cliente')}</b> · ${esc(w.whatsapp||'Sem WhatsApp')}<br><span class="muted">${fmtDate(w.desired_date+'T12:00:00Z')} · ${String(w.from_time).slice(0,5)} às ${String(w.to_time).slice(0,5)} · ${fmtDate(w.created_at)}</span><br>${(w.service_ids||[]).map(id=>esc(names[id]||'Serviço')).join(' + ')}<br><span class="badge">${({active:'Aguardando',notified:'Convite enviado',booked:'Agendado',cancelled:'Cancelado',expired:'Expirado'})[w.status]||w.status}</span>${w.offer?`<p class="hint">Oferta: ${fmtDate(w.offer.offered_start)} ${fmtTime(w.offer.offered_start)} · expira ${fmtTime(w.offer.expires_at)} · ${esc(w.offer.status)}</p>`:''}</div><div class="row">${w.status==='active'||w.status==='notified'?`<button class="btn small ghost" data-cancel="${w.id}">Cancelar pedido</button>`:''}${w.status==='cancelled'?`<button class="btn small ghost" data-reactivate="${w.id}">Reativar</button>`:''}${w.whatsapp?`<a class="btn small ghost" target="_blank" rel="noopener" href="https://wa.me/55${onlyDigits(w.whatsapp).slice(-11)}">WhatsApp</a>`:''}</div></div>`).join('')||'Nenhum pedido na lista de espera.'}</div>`);
 $('#reload').onclick=()=>viewListaEspera(root);$('#process').onclick=()=>guard(async()=>{await api.rpc('admin_waitlist_process_date',{p_date:$('#wdate').value});toast('Fila processada. Se houver vaga compatível, o próximo cliente elegível receberá uma notificação interna.','success');await viewListaEspera(root)});
 $$('[data-cancel]').forEach(b=>b.onclick=()=>guard(async()=>{await api.rpc('admin_waitlist_set_status',{p_id:b.dataset.cancel,p_status:'cancelled'});await viewListaEspera(root)}));$$('[data-reactivate]').forEach(b=>b.onclick=()=>guard(async()=>{await api.rpc('admin_waitlist_set_status',{p_id:b.dataset.reactivate,p_status:'active'});await viewListaEspera(root)}));
}

export async function viewKits(root){const [kits,products]=await Promise.all([api.select('kits','select=*&order=name'),api.select('products','select=id,name,quantity&is_active=eq.true&order=name')]);const items=await api.select('kit_items','select=*');root.innerHTML=wrap('Kits','<button class="btn" id="add">+ Kit</button>',`<div class="card">${kits.map(k=>`<div class="svc"><div><b>${esc(k.name)}</b><br>${money(k.price)} · ${k.is_active?'Ativo':'Inativo'}</div><button class="btn small ghost" data-edit="${k.id}">Editar</button></div>`).join('')||'Nenhum kit cadastrado.'}</div>`);const form=async k=>{const current=items.filter(i=>i.kit_id===k?.id);const d=dlg(`<form id="kitf"><h2>${k?'Editar':'Novo'} kit</h2>${field('name','Nome','text',k?.name)}${field('description','Descrição','text',k?.description)}${field('photo','URL da imagem','text',k?.photo_url)}${field('price','Preço do kit (R$)','number',k?.price??'','min="0" step="0.01"')}<h3>Composição</h3>${products.map(p=>{const it=current.find(i=>i.product_id===p.id);return `<label class="check"><input type="checkbox" data-prod="${p.id}" ${it?'checked':''}> ${esc(p.name)} <span class="muted">(estoque ${p.quantity})</span><input data-qty="${p.id}" type="number" min="1" value="${it?.quantity||1}" style="width:72px"></label>`}).join('')}<label class="check"><input id="active" type="checkbox" ${k?.is_active===false?'':'checked'}> Ativo</label><p class="err" id="err"></p><button class="btn" type="submit">Salvar kit</button></form>`);saveForm(d,'kitf',async()=>{const v={name:$('#name',d).value.trim(),description:$('#description',d).value,photo_url:$('#photo',d).value||null,price:Number($('#price',d).value),is_active:$('#active',d).checked};let id=k?.id;if(k)await api.update('kits','id=eq.'+id,v);else id=(await api.insert('kits',[v]))[0].id;await api.remove('kit_items','kit_id=eq.'+id);const chosen=$$('[data-prod]:checked',d).map(x=>({kit_id:id,product_id:x.dataset.prod,quantity:Math.max(1,Number($(`[data-qty="${x.dataset.prod}"]`,d).value)||1)}));if(chosen.length)await api.insert('kit_items',chosen);toast('Kit salvo.','success');viewKits(root)})};$('#add').onclick=()=>form(null);$$('[data-edit]').forEach(b=>b.onclick=()=>form(kits.find(x=>x.id===b.dataset.edit)))}
